"""Load the knowledge graph once per process and answer the frontend's graph questions."""

import json
import threading

import networkx as nx

from .build import GRAPH_FILE, GROUPS, build_and_save

_LOCK = threading.Lock()
_CACHE: dict = {}


def get_graph(rebuild: bool = False) -> tuple[nx.MultiDiGraph, dict]:
    """(graph, meta). Built from the processed tables the first time if the file is missing."""
    with _LOCK:
        if rebuild or "g" not in _CACHE:
            if rebuild or not GRAPH_FILE.exists():
                build_and_save()
            payload = json.loads(GRAPH_FILE.read_text())
            _CACHE["g"] = nx.node_link_graph(payload["graph"], directed=True, multigraph=True, edges="edges")
            _CACHE["meta"] = payload["meta"]
        return _CACHE["g"], _CACHE["meta"]


def node_view(g: nx.MultiDiGraph, node_id: str, per_rel: int = 12) -> dict | None:
    """A node's attributes and provenance, plus its neighbours grouped by relation (capped per relation)."""
    if node_id not in g:
        return None
    attrs = dict(g.nodes[node_id])
    groups: dict = {}
    for direction, edges in (("out", g.out_edges(node_id, data=True)), ("in", g.in_edges(node_id, data=True))):
        for u, v, d in edges:
            other = v if direction == "out" else u
            key = f"{direction}:{d['rel']}"
            grp = groups.setdefault(key, {"rel": d["rel"], "direction": direction, "total": 0, "items": []})
            grp["total"] += 1
            if len(grp["items"]) < per_rel:
                o = g.nodes[other]
                grp["items"].append({"id": other, "type": o["type"], "label": o["label"],
                                     "edge": {k: x for k, x in d.items() if k != "rel"}})
    return {"id": node_id, "type": attrs.pop("type"), "group": attrs.pop("group", GROUPS.get(attrs.get("type"))),
            "label": attrs.pop("label"), "prov": attrs.pop("prov"), "attributes": attrs,
            "neighbours": sorted(groups.values(), key=lambda x: (x["direction"], -x["total"]))}

"""OpenAI access for the three agents.

Configuration (environment variables, or a git-ignored `.env` file in the repo root):
    OPENAI_API_KEY             required for the LLM agents and embeddings
    OPENAI_RETRIEVER_MODEL     default gpt-6-luna   (Agent 1: idea -> IdeaSpec)
    OPENAI_EXPLAINER_MODEL     default gpt-6-terra  (Agent 2: facts -> PM explanation)
    OPENAI_VERIFIER_MODEL      default gpt-6-luna   (Agent 3: semantic check of each claim)
    OPENAI_EMBEDDING_MODEL     default text-embedding-3-small (semantic matching of ideas)

A configured model that the account cannot use is reported with the models it can
use; it is never replaced by another model silently.
"""

import os
import threading

import numpy as np
from pydantic import BaseModel

from .. import config

ROLES = ("retriever", "explainer", "verifier", "embedding")
DEFAULT_MODELS = {"retriever": "gpt-6-luna", "explainer": "gpt-6-terra", "verifier": "gpt-6-luna",
                  "embedding": "text-embedding-3-small"}
ENV_VARS = {"retriever": "OPENAI_RETRIEVER_MODEL", "explainer": "OPENAI_EXPLAINER_MODEL",
            "verifier": "OPENAI_VERIFIER_MODEL", "embedding": "OPENAI_EMBEDDING_MODEL"}


class LLMError(RuntimeError):
    """A call to the language model failed or returned nothing usable."""


class LLMUnavailable(LLMError):
    """No API key is configured."""


class ModelUnavailable(LLMError):
    """The configured model is not available to this API key."""


def _dotenv() -> dict:
    path = config.ROOT / ".env"
    out = {}
    if path.exists():
        for line in path.read_text().splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            out[k.strip().removeprefix("export ").strip()] = v.strip().strip('"').strip("'")
    return out


def setting(name: str, default: str | None = None) -> str | None:
    return os.environ.get(name) or _dotenv().get(name) or default


def model_config() -> dict:
    return {role: setting(ENV_VARS[role], DEFAULT_MODELS[role]) for role in ROLES}


class OpenAILLM:
    """Thin wrapper: structured parsing into Pydantic models, embeddings, model availability."""

    provider = "openai"

    def __init__(self, api_key: str, models: dict | None = None, timeout: float = 180.0):
        from openai import OpenAI
        self.client = OpenAI(api_key=api_key, timeout=timeout, max_retries=2)
        self.models = models or model_config()
        self._available: set | None = None
        self._listing_error: str | None = None
        self._lock = threading.Lock()

    # -------------------------------------------------------------- availability
    def available_models(self, refresh: bool = False) -> set | None:
        """Model ids this key can use, or None if the key may not list models."""
        import openai
        with self._lock:
            if self._available is None or refresh:
                try:
                    self._available = {m.id for m in self.client.models.list()}
                    self._listing_error = None
                except openai.AuthenticationError as e:
                    raise LLMError(f"OpenAI rejected the API key: {_msg(e)}") from e
                except openai.OpenAIError as e:
                    self._available, self._listing_error = None, _msg(e)
            return self._available

    def check_models(self, refresh: bool = False) -> dict:
        avail = self.available_models(refresh)
        roles = {r: {"model": m, "available": None if avail is None else m in avail} for r, m in self.models.items()}
        similar = sorted(m for m in (avail or ()) if m.startswith(("gpt-6", "gpt-5", "text-embedding")))
        return {"roles": roles, "listing_error": self._listing_error, "similar_models": similar[:40]}

    def _model(self, role: str) -> str:
        model = self.models[role]
        avail = self.available_models()
        if avail is not None and model not in avail:
            options = sorted(m for m in avail if m.startswith(("gpt-", "text-embedding")))
            raise ModelUnavailable(f"The {role} model '{model}' is not available to this API key. Set "
                                   f"{ENV_VARS[role]} to one of: {', '.join(options[:30]) or '(none listed)'}")
        return model

    # -------------------------------------------------------------- calls
    def parse(self, role: str, instructions: str, input_text: str, schema: type[BaseModel]) -> BaseModel:
        import openai
        model = self._model(role)
        try:
            resp = self.client.responses.parse(model=model, instructions=instructions, input=input_text,
                                               text_format=schema, store=False)
        except openai.OpenAIError as e:
            raise LLMError(f"{model}: {_msg(e)}") from e
        parsed = resp.output_parsed
        if parsed is None:
            raise LLMError(f"{model} returned no structured output (status {resp.status}, "
                           f"details {resp.incomplete_details})")
        return parsed

    def embed(self, texts: list[str], model: str | None = None) -> np.ndarray:
        import openai
        model = model or self._model("embedding")
        try:
            resp = self.client.embeddings.create(model=model, input=texts)
        except openai.OpenAIError as e:
            raise LLMError(f"{model}: {_msg(e)}") from e
        return np.array([d.embedding for d in resp.data], dtype=float)


def _msg(e: Exception) -> str:
    body = getattr(e, "body", None)
    if isinstance(body, dict) and isinstance(body.get("error"), dict):
        return body["error"].get("message") or str(e)
    return str(e)


def from_env() -> OpenAILLM | None:
    key = setting("OPENAI_API_KEY")
    return OpenAILLM(key) if key else None

"""The part of the knowledge graph one evaluation touches, ready for the graph view.

Nodes: the idea, its candidate and chosen features, everything a fact cites
(verdict cells, survey scores, sales, price-list items, comments, model terms,
caveats) and the structure that connects them (domain, reasons, series,
markets, fitment). Request-time nodes - the idea and one recommendation per
series x market cell - are added so the PM can see how the model outputs feed
each recommendation. Capped so the view stays readable; cited nodes are kept first.
"""

from ..graph.build import GROUPS, nid
from .contracts import FactBundle, IdeaSpec

CAP = 170
DROP_ORDER = ["Comment", "OptionItem", "TechSpec", "Reason", "SurveyAttribute", "SalesVolume", "SurveyScore",
              "VerdictCell", "FitmentSummary", "EBMTerm", "Caveat"]


def subgraph(g, spec: IdeaSpec, result: dict, bundle: FactBundle, candidates: list) -> dict:
    nodes: dict = {}
    edges: dict = {}
    cited = {f.source.node_id for f in bundle.facts if f.source.node_id}

    def add(node_id, **extra):
        if node_id in nodes:
            nodes[node_id].update({k: v for k, v in extra.items() if v})
            return
        if node_id in g:
            d = g.nodes[node_id]
            nodes[node_id] = {"id": node_id, "type": d["type"], "group": d["group"], "label": d["label"]}
        nodes[node_id].update(extra) if node_id in nodes else None

    def virtual(node_id, type_, group, label):
        nodes.setdefault(node_id, {"id": node_id, "type": type_, "group": group, "label": label, "virtual": True})

    def link(u, v, rel, **attrs):
        if u in nodes and v in nodes:
            edges.setdefault((u, v, rel), {"id": f"{u}->{v}:{rel}", "source": u, "target": v, "rel": rel, **attrs})

    virtual("idea:current", "Idea", "idea", spec.idea[:80])
    chosen = {f.feature for f in spec.features}
    for c in candidates[:6]:
        add(c.node_id, chosen=c.feature in chosen)
    for f in spec.features:
        add(f.node_id, chosen=True)

    for node_id in cited:
        if node_id in g:
            add(node_id, cited=True)

    for fr in result["features"]:
        f = fr["feature"]
        fn = nid("feature", f)
        add(fn, chosen=True)
        add(nid("domain", fr["domain"]))
        add(nid("verdict", "feature", f))
        reasons = sorted(((d.get("n_comments") or 0, v) for _, v, d in g.out_edges(fn, data=True)
                          if d["rel"] == "HAS_REASON"), reverse=True)[:5]
        for _, v in reasons:
            add(v)
        for u, _, d in g.in_edges(fn, data=True):
            if d["rel"] == "MEASURES":
                add(u)
        for m in result["models"]:
            add(nid("series", m))
            if nid("fitment", f, m) in g:
                add(nid("fitment", f, m))
        for k in result["markets"]:
            add(nid("market", k))
        for cell in fr["cells"]:
            rec = f"rec:{f}|{cell['model']}|{cell['market']}"
            label = f"{cell['model']} {cell['market']}: {cell['recommendation']}"
            if cell.get("score") is not None and cell["recommendation"] != "Not sold":
                label += f" ({cell['score']:.2f})"
            virtual(rec, "Recommendation", "model_output", label)
            nodes[rec]["recommendation"] = cell["recommendation"]
    for term in ("domain", "market", "model"):
        if nid("ebmterm", term) in g:
            add(nid("ebmterm", term))
    for m in ("complaint_ebm", "feature_classifier"):
        add(nid("model", m))

    _cap(nodes, cited)

    # edges: idea -> candidates, recommendation cells -> their evidence, then all graph edges among kept nodes
    for c in candidates[:6]:
        link("idea:current", c.node_id, "MATCHED" if c.feature in chosen else "CANDIDATE",
             detail=", ".join(c.how))
    for fact in bundle.facts:
        src = fact.source.node_id
        if src and src.startswith("rec:"):
            continue
        if fact.feature and fact.series and fact.market:
            link(f"rec:{fact.feature}|{fact.series}|{fact.market}", src, "USES", fact=fact.id)
    for fr in result["features"]:
        for cell in fr["cells"]:
            rec = f"rec:{fr['feature']}|{cell['model']}|{cell['market']}"
            link(rec, nid("feature", fr["feature"]), "EVALUATES")
            link(rec, nid("series", cell["model"]), "FOR_SERIES")
            link(rec, nid("market", cell["market"]), "IN_MARKET")
    real = [n for n in nodes if n in g]
    keep = set(real)
    for u in real:
        for _, v, d in g.out_edges(u, data=True):
            if v in keep:
                link(u, v, d["rel"])
    for n in nodes.values():
        n["cited"] = bool(n.get("cited")) or n["id"] in cited
        n.setdefault("group", GROUPS.get(n["type"], "other"))
    return {"nodes": list(nodes.values()), "edges": list(edges.values()),
            "n_cited": sum(1 for n in nodes.values() if n["cited"])}


def _cap(nodes: dict, cited: set) -> None:
    for t in DROP_ORDER:
        if len(nodes) <= CAP:
            return
        drop = [k for k, v in nodes.items() if v["type"] == t and not v.get("virtual") and not v.get("chosen")]
        drop.sort(key=lambda k: k in cited)            # uncited first
        for k in drop[: len(nodes) - CAP]:
            del nodes[k]

