  --muted: var(--disclaimer);
  --muted-soft: #8e8e8e;
  --on-dark: #fff;
  --on-dark-soft: #e6e6e6;
  --primary: var(--cta);
  --primary-active: var(--cta-hover);
  --primary-disabled: var(--cta-disabled);
  --focus: var(--cta);
  --data-blue: var(--cta);
