  --status-error: var(--error);
  --fs-caption: var(--fs-label);
  --fs-body-sm: var(--fs-small);
  --fs-title-sm: var(--fs-sub2);
  --fs-title-md: var(--fs-sub1);
  --fs-title-lg: 20px;
  --fs-display-sm: var(--fs-h3);
  --fs-display-md: var(--fs-h2);
}

@media (max-width: 1280px) {
