/* ------------------------------------------------------------------ tables */
.table-scroll { overflow-x: auto; }
.table th, .table td { padding: 12px 16px 12px 0; text-align: left; border-bottom: 1px solid var(--border); vertical-align: top; font-size: var(--fs-small); }
.table th { font-weight: var(--w-input); color: var(--disclaimer); font-size: var(--fs-label); white-space: nowrap; }
