import { useEffect, useState } from "react";

// All data comes from the FastAPI backend (bmw_feedback/api.py); nothing is hard-coded here.

/** An API error with the backend's machine-readable code when it sends one (e.g. "llm_unavailable"). */
export class ApiError extends Error {
  constructor(message: string, public status: number, public code: string | null = null) {
    super(message);
  }
}

async function failure(res: Response): Promise<ApiError> {
  let message = `${res.status} ${res.statusText}`;
  let code: string | null = null;
  try {
    const j = await res.json();
    const d = j.detail;
    if (typeof d === "string") message = d;
    else if (d && typeof d === "object" && !Array.isArray(d)) {
      message = d.message ?? JSON.stringify(d);
      code = d.code ?? null;
    } else if (Array.isArray(d)) message = d.map((e: { loc?: unknown[]; msg?: string }) => `${(e.loc ?? []).join(".")}: ${e.msg}`).join("; ");
  } catch {
    /* keep the status text */
  }
  return new ApiError(message, res.status, code);
}

export async function getJSON<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw await failure(res);
  return res.json() as Promise<T>;
}

export async function postJSON<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  if (!res.ok) throw await failure(res);
  return res.json() as Promise<T>;
}

export function useApi<T>(path: string | null) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(Boolean(path));
  useEffect(() => {
    if (!path) return;
    let live = true;
    setLoading(true);
    setError(null);
    getJSON<T>(path)
      .then((d) => live && setData(d))
      .catch((e: Error) => live && setError(e.message))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [path]);
  return { data, error, loading };
}

export const fmtInt = (v: number | null | undefined) => (v === null || v === undefined ? "–" : Math.round(v).toLocaleString("en-GB"));
export const fmtNum = (v: number | null | undefined, d = 2) => (v === null || v === undefined || Number.isNaN(v) ? "–" : v.toFixed(d));
export const fmtEur = (v: number | null | undefined) => (v === null || v === undefined ? "–" : `EUR ${Math.round(v).toLocaleString("en-GB")}`);
export const fmtPct = (v: number | null | undefined, d = 0) => (v === null || v === undefined ? "–" : `${(v * 100).toFixed(d)}%`);

export const MODEL_NAMES: Record<string, string> = { F70: "1 Series", G60: "5 Series", G70: "7 Series" };
export const SERIES_LABELS: Record<string, string> = { F70: "1 Series (F70)", G60: "5 Series (G60)", G70: "7 Series (G70)" };
export const MARKET_NAMES: Record<string, string> = { EU: "Europe", US: "United States", CN: "China", RoW: "Rest of world" };
export const MOVE_LABELS: Record<string, string> = {
  fix_existing: "Fix or improve what exists",
  make_standard: "Make it standard equipment",
  new_option: "Offer it as a new option",
  price_change: "Change the price",
  introduce_on_series: "Introduce it on another series",
  unspecified: "Not specified",
};

import { useState } from "react";
import type { AgentStatus } from "../types";

/** bmw.de global navigation over the stage: white roundel, white type, 1px rule under the bar. */
export default function BrandHeader({ status }: { status: AgentStatus | null }) {
  const [logo, setLogo] = useState(true);
  const ready = status?.llm_configured;
  return (
    <header className="nav">
      <div className="wrap nav__inner">
        <a href="#top" className="brand" aria-label="Product Idea Evaluation, back to the top">
          {logo ? (
            <img className="brand__logo" src="/brand/bmw-logo-white.svg" width={52} height={52} alt="BMW" onError={() => setLogo(false)} />
          ) : (
            <span className="brand__wordmark">BMW</span>
          )}
          <span className="brand__name">Product Idea Evaluation</span>
        </a>
        {status && (
          <span className={`nav__status ${ready ? "nav__status--ok" : "nav__status--warn"}`} title={status.message ?? undefined}>
            <span className="nav__dot" aria-hidden />
            {ready
              ? `Agents ready: ${status.models.retriever} · ${status.models.explainer}`
              : "Explanation agents offline: no OpenAI key"}
          </span>
        )}
      </div>
    </header>
  );
}

import { fmtInt } from "../api";
import type { AgentStatus } from "../types";

// Ideas a PM might bring; the last one has no customer evidence in the data on purpose.
export const EXAMPLES = [
  "Make seat massage standard on the 5 Series in Europe",
  "Fix the wireless phone charger overheating",
  "Head-up display on the 1 Series for EUR 990",
  "Offer automatic doors on the 5 Series",
  "A vacuum for pet hair in the boot",
];

/** bmw.de stage: uppercase 500 headline, uppercase subline, light copy, blue CTA + outline secondary. */
export default function IdeaHero({
  idea,
  setIdea,
  onSubmit,
  busy,
  status,
}: {
  idea: string;
  setIdea: (v: string) => void;
  onSubmit: (text: string) => void;
  busy: boolean;
  status: AgentStatus | null;
}) {
  return (
    <section className="stage" id="top" aria-labelledby="stage-title">
      <div className="wrap stage__inner">
        <h1 id="stage-title" className="stage__title">
          Evaluate a product idea
        </h1>
        <p className="stage__sub">Grounded in customer data. Verified claim by claim.</p>
        <p className="stage__copy">
          Describe a feature idea for the 1, 5 or 7 Series. Three agents match it to the knowledge graph
          {status ? ` (${fmtInt(status.graph.nodes)} nodes linking feedback, studies, sales, price lists and model outputs)` : ""},
          explain the evidence for product management and check every sentence against the data.
        </p>
        <form
          className="stage__form"
          onSubmit={(e) => {
            e.preventDefault();
            if (idea.trim()) onSubmit(idea.trim());
          }}
        >
          <label htmlFor="idea" className="sr-only">
            Your feature idea
          </label>
          <input
            id="idea"
            className="input stage__input"
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="For example: make seat massage standard on the 5 Series in Europe"
            autoComplete="off"
            maxLength={2000}
          />
          <button className="btn stage__cta" type="submit" disabled={busy || !idea.trim()}>
            {busy ? "Reading your idea…" : "Evaluate idea"}
          </button>
        </form>
        <div className="stage__examples">
          <span className="stage__examples-label">Try an example</span>
          <div className="chips">
            {EXAMPLES.map((ex) => (
              <button
                key={ex}
                type="button"
                className="chip chip--on-dark"
                disabled={busy}
                onClick={() => {
                  setIdea(ex);
                  onSubmit(ex);
                }}
              >
                {ex}
              </button>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

import type { AgentEvaluation, AgentStatus, Explained, InterpretResult } from "../types";

export type Phase = "idle" | "interpreting" | "review" | "evaluating" | "done";
export type ExplainState = "idle" | "running" | "done" | "unavailable" | "error" | "stale";
type StepState = "waiting" | "running" | "done" | "off" | "error";

const STATE_TEXT: Record<StepState, string> = { waiting: "Waiting", running: "Working", done: "Done", off: "Not available", error: "Failed" };

/** The pipeline as four steps: three agents around the deterministic decision engine. */
export default function AgentSteps({
  status,
  phase,
  interp,
  evaluation,
  explainState,
  explained,
}: {
  status: AgentStatus | null;
  phase: Phase;
  interp: InterpretResult | null;
  evaluation: AgentEvaluation | null;
  explainState: ExplainState;
  explained: Explained | null;
}) {
  const m = status?.models ?? {};
  const llm = Boolean(status?.llm_configured);
  const agentState = (): StepState =>
    explainState === "running" ? "running" : explainState === "done" ? "done" : explainState === "unavailable" ? "off"
      : explainState === "error" ? "error" : "waiting";
  const steps: { n: string; title: string; who: string; what: string; state: StepState; result?: string }[] = [
    {
      n: "01",
      title: "Retriever agent",
      who: llm ? m.retriever : "rules (no API key)",
      what: "Matches the idea to features in the knowledge graph and validates the result.",
      state: phase === "interpreting" ? "running" : interp ? "done" : "waiting",
      result: interp ? `${interp.spec.features.length} feature(s), ${interp.candidates.length} candidates` : undefined,
    },
    {
      n: "02",
      title: "Decision engine",
      who: "deterministic, no LLM",
      what: "Computes every number from the processed data and model outputs and cites graph nodes.",
      state: phase === "evaluating" ? "running" : evaluation ? "done" : "waiting",
      result: evaluation ? `${evaluation.facts.length} facts` : undefined,
    },
    {
      n: "03",
      title: "Explainer agent",
      who: llm ? m.explainer : "needs an OpenAI key",
      what: "Writes the brief for product management. Every claim cites fact IDs.",
      state: !llm && evaluation ? "off" : agentState(),
      result: explained ? `${explained.verification.claims.length} claims, ${explained.explanation.attempts} draft(s)` : undefined,
    },
    {
      n: "04",
      title: "Verifier agent",
      who: llm ? `rules + ${m.verifier}` : "needs an OpenAI key",
      what: "Checks numbers, labels, quotes and scope, then entailment. Failures are rewritten once, then removed.",
      state: !llm && evaluation ? "off" : agentState(),
      result: explained ? `${explained.verification.n_verified} verified, ${explained.verification.n_removed} removed` : undefined,
    },
  ];
  return (
    <ol className="steps" aria-label="Evaluation pipeline">
      {steps.map((s) => (
        <li key={s.n} className={`step step--${s.state}`}>
          <div className="spread">
            <span className="step__n">{s.n}</span>
            <span className="step__state">
              <span className="step__dot" aria-hidden />
              {STATE_TEXT[s.state]}
            </span>
          </div>
          <p className="step__title">{s.title}</p>
          <p className="caption">{s.who}</p>
          <p className="small step__what">{s.what}</p>
          {s.result && <p className="small step__result">{s.result}</p>}
        </li>
      ))}
    </ol>
  );
}

import { MARKET_NAMES, MOVE_LABELS, SERIES_LABELS, fmtInt, fmtNum } from "../api";
import type { Candidate, IdeaSpec, InterpretResult, Move } from "../types";
import { Verdict } from "./marks";

const MAX_FEATURES = 3;
const METHOD_NAMES: Record<string, string> = { name_or_alias: "name / alias", classifier: "classifier", semantic: "semantic" };

/** Step 1 output, editable: the PM confirms what the retriever read before anything is evaluated. */
export default function SpecReview({
  interp,
  draft,
  setDraft,
  onEvaluate,
  busy,
}: {
  interp: InterpretResult;
  draft: IdeaSpec;
  setDraft: (s: IdeaSpec) => void;
  onEvaluate: () => void;
  busy: boolean;
}) {
  const chosen = new Set(draft.features.map((f) => f.feature));
  const failed = interp.attempts.filter((a) => !a.ok);
  const byLLM = interp.method.startsWith("llm:");

  function toggleFeature(c: Candidate) {
    let features = draft.features;
    if (chosen.has(c.feature)) features = features.filter((f) => f.feature !== c.feature);
    else if (features.length < MAX_FEATURES)
      features = [...features, { feature: c.feature, node_id: c.node_id, reason: "selected by the PM", methods: c.methods }];
    else return;
    const novelty = features.length === 0 ? "new_to_data" : draft.novelty === "new_to_data" ? "related_only" : draft.novelty;
    setDraft({ ...draft, features, novelty });
  }
  const toggle = (key: "series" | "markets", v: string) =>
    setDraft({ ...draft, [key]: draft[key].includes(v) ? draft[key].filter((x) => x !== v) : [...draft[key], v] });

  return (
    <div className="review stack-lg">
      <div className="stack">
        <p className="eyebrow">Step 1 · Retriever agent</p>
        <h2 className="section-title">Is this what you want to evaluate?</h2>
        <p className="lead">{draft.summary}</p>
        <p className="caption">
          {byLLM ? `Read by ${interp.method.slice(4)}` : "Read by transparent rules (no language model)"}. Candidates come from feature
          names and aliases, the trained feature classifier and the {interp.semantic_method} index over the knowledge graph; the
          agent may only choose among them and its answer is validated before you see it.
        </p>
        {failed.length > 0 && (
          <p className="note note--warn">
            <strong>Validation caught {failed.length} invalid answer{failed.length > 1 ? "s" : ""}.</strong>{" "}
            {failed[0].errors.slice(0, 2).join(" ")}{" "}
            {interp.attempts.some((a) => a.ok) ? "The agent corrected it." : "The rules below were used instead."}
          </p>
        )}
        {interp.semantic_error && <p className="note">{interp.semantic_error}</p>}
      </div>

      <fieldset className="review__group">
        <legend className="review__legend">
          Features in the customer data <span className="caption">choose up to {MAX_FEATURES}</span>
        </legend>
        {interp.candidates.length === 0 && <p className="small muted">No candidate features were found.</p>}
        <div className="tiles">
          {interp.candidates.map((c) => (
            <button
              key={c.feature}
              type="button"
              className="tile"
              aria-pressed={chosen.has(c.feature)}
              onClick={() => toggleFeature(c)}
              disabled={!chosen.has(c.feature) && draft.features.length >= MAX_FEATURES}
            >
              <span className="spread">
                <span className="tile__title">{c.feature}</span>
                {chosen.has(c.feature) && <span className="tile__check" aria-hidden />}
              </span>
              <span className="caption">{c.domain}</span>
              <span className="row small" style={{ gap: 12 }}>
                <Verdict verdict={c.verdict} />
                <span className="muted num">{fmtInt(c.n_comments)} comments</span>
              </span>
              <span className="tile__methods">
                {Object.entries(c.methods).map(([k, v]) => (
                  <span key={k} className="method">
                    {METHOD_NAMES[k] ?? k} <span className="num">{fmtNum(v)}</span>
                  </span>
                ))}
              </span>
              {c.umbrella && <span className="caption">Umbrella label: general praise is filed here.</span>}
            </button>
          ))}
        </div>
        {draft.features.length === 0 && (
          <p className="note note--info">
            No feature selected: the idea is evaluated as <strong>new to the data</strong>. The brief will say what the data cannot
            tell you and show the nearest features.
          </p>
        )}
      </fieldset>

      <div className="review__grid">
        <fieldset className="review__group">
          <legend className="review__legend">
            Series <span className="caption">none selected = all</span>
          </legend>
          <div className="chips">
            {Object.entries(SERIES_LABELS).map(([k, label]) => (
              <button key={k} type="button" className="chip" aria-pressed={draft.series.includes(k)} onClick={() => toggle("series", k)}>
                {label}
              </button>
            ))}
          </div>
        </fieldset>
        <fieldset className="review__group">
          <legend className="review__legend">
            Markets <span className="caption">none selected = all</span>
          </legend>
          <div className="chips">
            {Object.entries(MARKET_NAMES).map(([k, label]) => (
              <button key={k} type="button" className="chip" aria-pressed={draft.markets.includes(k)} onClick={() => toggle("markets", k)}>
                {label}
              </button>
            ))}
          </div>
        </fieldset>
        <div className="field">
          <label htmlFor="move">Proposed move</label>
          <select id="move" className="select" value={draft.move} onChange={(e) => setDraft({ ...draft, move: e.target.value as Move })}>
            {Object.entries(MOVE_LABELS).map(([k, label]) => (
              <option key={k} value={k}>
                {label}
              </option>
            ))}
          </select>
        </div>
        <div className="field">
          <label htmlFor="price">Proposed price (EUR, optional)</label>
          <input
            id="price"
            className="input num"
            type="number"
            min={1}
            step={10}
            inputMode="numeric"
            value={draft.proposed_price_eur ?? ""}
            onChange={(e) => setDraft({ ...draft, proposed_price_eur: e.target.value === "" ? null : Number(e.target.value) })}
            placeholder="e.g. 990"
          />
        </div>
      </div>

      {draft.ambiguities.length > 0 && (
        <div className="note note--info">
          <strong>Please check:</strong>
          <ul className="bullets">
            {draft.ambiguities.map((a, i) => (
              <li key={i}>{a}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="row">
        <button className="btn" type="button" onClick={onEvaluate} disabled={busy}>
          {busy ? "Evaluating…" : "Evaluate this idea"}
        </button>
        <span className="caption measure">
          The decision engine computes every number from the processed data and model outputs. No language model is involved in this step.
        </span>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import type { Claim, Explained, Fact } from "../types";
import type { ExplainState } from "./AgentSteps";

const TITLES: Record<string, string> = {
  customer_evidence: "What customers say",
  market_view: "Where it matters",
  price_and_equipment: "Price and equipment today",
  risks_and_caveats: "Risks and limits of the evidence",
  next_steps: "Recommended next steps",
};

/** Citation numbers in order of first use across the brief. */
export function citationNumbers(explained: Explained | null): Map<string, number> {
  const map = new Map<string, number>();
  if (!explained) return map;
  const order = ["headline", ...Object.keys(TITLES)];
  for (const s of order)
    for (const c of explained.explanation.sections[s] ?? []) for (const id of c.fact_ids) if (!map.has(id)) map.set(id, map.size + 1);
  return map;
}

export default function ExplanationView({
  explained,
  state,
  error,
  facts,
  onExplain,
  onShowNode,
}: {
  explained: Explained | null;
  state: ExplainState;
  error: string | null;
  facts: Fact[];
  onExplain: () => void;
  onShowNode: (id: string) => void;
}) {
  const index = new Map(facts.map((f) => [f.id, f]));
  const numbers = citationNumbers(explained);

  if (state === "running")
    return (
      <div className="explain explain--loading" role="status">
        <p className="small">The explainer is writing the brief; the verifier then checks every claim against the facts…</p>
        <div className="skeleton" style={{ width: "80%", height: 28 }} />
        <div className="skeleton" style={{ width: "60%" }} />
        <div className="skeleton" style={{ width: "70%" }} />
      </div>
    );
  if (state === "unavailable")
    return (
      <div className="note note--warn">
        <strong>The written explanation is not available.</strong> {error}
      </div>
    );
  if (state === "error")
    return (
      <div className="note note--error stack">
        <p>
          <strong>The explanation could not be produced.</strong> {error} Nothing unverified is shown.
        </p>
        <button className="btn btn--dark btn--small" onClick={onExplain}>
          Try again
        </button>
      </div>
    );
  if (state === "stale" || (!explained && state === "idle"))
    return (
      <div className="note note--info stack">
        <p>
          {state === "stale"
            ? "The decision policy changed, so the numbers above were recomputed. Generate the explanation again for them."
            : "Generate the written brief for this evaluation."}
        </p>
        <button className="btn btn--small" onClick={onExplain}>
          Generate explanation
        </button>
      </div>
    );
  if (!explained) return null;

  const s = explained.explanation.sections;
  const headline = s.headline ?? [];
  const v = explained.verification;
  return (
    <div className="explain">
      <div className="explain__headline">
        {headline.length ? (
          headline.map((c) => <ClaimText key={c.id} claim={c} numbers={numbers} index={index} onShowNode={onShowNode} />)
        ) : (
          <p className="small muted">The headline did not pass verification and was removed; see the verification report.</p>
        )}
      </div>
      <div className="explain__grid">
        {Object.entries(TITLES).map(([key, title]) =>
          (s[key] ?? []).length ? (
            <section key={key} className="card explain__card" aria-label={title}>
              <h3 className="explain__title">{title}</h3>
              <ul className="claims">
                {(s[key] ?? []).map((c) => (
                  <li key={c.id} className="claim">
                    <span className="claim__ok" title="Verified against the cited facts" aria-label="verified" />
                    <ClaimText claim={c} numbers={numbers} index={index} onShowNode={onShowNode} />
                  </li>
                ))}
              </ul>
            </section>
          ) : null,
        )}
      </div>
      <p className="disclaimer">
        Written by {explained.explanation.model}. {v.n_verified} claim{v.n_verified === 1 ? "" : "s"} passed the verifier (rules:{" "}
        {v.rules.join(", ")}; semantic check: {v.semantic_model}); {v.n_removed} removed
        {explained.explanation.attempts > 1 ? " after one rewrite of the first draft" : ""}. Numbers in brackets cite the facts each
        claim relies on.
      </p>
    </div>
  );
}

function ClaimText({
  claim,
  numbers,
  index,
  onShowNode,
}: {
  claim: Claim;
  numbers: Map<string, number>;
  index: Map<string, Fact>;
  onShowNode: (id: string) => void;
}) {
  return (
    <p className="claim__text">
      {claim.text}{" "}
      {claim.fact_ids.map((id) => (
        <Cite key={id} n={numbers.get(id) ?? 0} fact={index.get(id)} id={id} onShowNode={onShowNode} />
      ))}
    </p>
  );
}

function Cite({ n, fact, id, onShowNode }: { n: number; fact?: Fact; id: string; onShowNode: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent | KeyboardEvent) => {
      if (e instanceof KeyboardEvent ? e.key === "Escape" : !ref.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    document.addEventListener("keydown", close);
    return () => {
      document.removeEventListener("mousedown", close);
      document.removeEventListener("keydown", close);
    };
  }, [open]);
  const src = fact?.source;
  return (
    <span className="cite" ref={ref}>
      <button type="button" className="cite__btn" aria-expanded={open} onClick={() => setOpen((o) => !o)} aria-label={`Source ${n}: ${id}`}>
        {n}
      </button>
      {open && (
        <span className="popover" role="dialog" aria-label={`Fact ${id}`}>
          <span className="popover__id">{id}</span>
          <span className="popover__text">{fact ? fact.statement : "This fact is not in the bundle."}</span>
          {src && (
            <span className="popover__src">
              {src.kind}: {src.ref}
              {src.key ? ` · ${src.key}` : ""}
              {src.page ? ` · page ${src.page}` : ""}
            </span>
          )}
          {src?.node_id && (
            <button
              type="button"
              className="textlink popover__link"
              onClick={() => {
                setOpen(false);
                onShowNode(src.node_id!);
              }}
            >
              Show in knowledge graph
            </button>
          )}
        </span>
      )}
    </span>
  );
}

import type { Claim, Explained, Fact } from "../types";

const RULE_NAMES: Record<string, string> = {
  citations: "Citations",
  numbers: "Numbers",
  labels: "Labels",
  quotes: "Quotes",
  scope: "Series / market",
  semantic: "Entailment",
};
const SECTION_NAMES: Record<string, string> = {
  headline: "Bottom line",
  customer_evidence: "Customers",
  market_view: "Markets",
  price_and_equipment: "Price",
  risks_and_caveats: "Risks",
  next_steps: "Next steps",
};

/** Agent 3's report: every claim, every check, what was rewritten and what was removed. */
export default function VerificationReport({ explained, facts }: { explained: Explained | null; facts: Fact[] }) {
  if (!explained) return <p className="small muted">The report appears once the explainer and verifier have run.</p>;
  const v = explained.verification;
  const index = new Map(facts.map((f) => [f.id, f]));
  return (
    <div className="stack-lg">
      <div className="facts-row">
        <Fig label="Verified claims" value={String(v.n_verified)} />
        <Fig label="Removed claims" value={String(v.n_removed)} />
        <Fig label="Failed in first draft" value={String(v.rewritten.length)} />
        <Fig label="Semantic checker" value={v.semantic_model ?? "–"} />
      </div>
      <p className="small measure">
        Each claim must cite facts from the decision engine. Rules check citations, numbers (at the precision written), recommendation
        and verdict labels, verbatim quotes and the series and markets named; the semantic checker then judges whether the cited facts
        entail the claim. Claims that fail are sent back for one rewrite and removed if they still fail.
      </p>
      <div className="table-scroll">
        <table className="table verify">
          <thead>
            <tr>
              <th>Status</th>
              <th>Section</th>
              <th>Claim</th>
              {v.rules.map((r) => (
                <th key={r} className="verify__rule">
                  {RULE_NAMES[r] ?? r}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {v.claims.map((c) => (
              <Row key={c.id} claim={c} rules={v.rules} index={index} />
            ))}
          </tbody>
        </table>
      </div>
      {v.rewritten.length > 0 && (
        <details>
          <summary>First-draft claims that failed and triggered the rewrite ({v.rewritten.length})</summary>
          <ul className="bullets small" style={{ marginTop: 12 }}>
            {v.rewritten.map((c) => (
              <li key={c.id}>
                “{c.text}” —{" "}
                {c.checks
                  .filter((ch) => !ch.passed)
                  .map((ch) => `${RULE_NAMES[ch.name] ?? ch.name}: ${ch.detail}`)
                  .join(" ")}
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

function Row({ claim, rules, index }: { claim: Claim; rules: string[]; index: Map<string, Fact> }) {
  const byName = new Map(claim.checks.map((c) => [c.name, c]));
  const removed = claim.status === "removed";
  return (
    <tr className={removed ? "verify__removed" : undefined}>
      <td>
        <span className={`pill ${removed ? "pill--error" : "pill--success"}`}>{removed ? "Removed" : "Verified"}</span>
      </td>
      <td className="caption">{SECTION_NAMES[claim.section] ?? claim.section}</td>
      <td>
        <p className="verify__text">{claim.text}</p>
        <p className="caption" title={claim.fact_ids.map((i) => `${i}: ${index.get(i)?.statement ?? "unknown"}`).join("\n")}>
          Cites {claim.fact_ids.length ? claim.fact_ids.join(", ") : "nothing"}
        </p>
        {removed && (
          <p className="caption error">
            {claim.checks
              .filter((c) => !c.passed)
              .map((c) => c.detail)
              .join(" ")}
          </p>
        )}
      </td>
      {rules.map((r) => {
        const ch = byName.get(r);
        return (
          <td key={r} className="verify__cell" title={ch ? ch.detail : "Not run (an earlier check failed)"}>
            {ch ? (
              <span className={ch.passed ? "tick" : "cross"} aria-label={`${r}: ${ch.passed ? "passed" : "failed"}. ${ch.detail}`} />
            ) : (
              <span className="caption" aria-label={`${r}: not run`}>
                –
              </span>
            )}
          </td>
        );
      })}
    </tr>
  );
}

function Fig({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="techfact__label">{label}</p>
      <p className="techfact__value num">{value}</p>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import cytoscape from "cytoscape";
import type { Core, ElementDefinition } from "cytoscape";
import { fmtInt, useApi } from "../api";
import type { AgentEvaluation, GraphSchema } from "../types";
import NodeInspector from "./NodeInspector";

// Colour (CSS token) and shape per node group; the legend always shows both.
const GROUPS: Record<string, { label: string; token: string; shape: string }> = {
  idea: { label: "Idea", token: "--g-idea", shape: "star" },
  feedback: { label: "Feedback", token: "--g-feedback", shape: "ellipse" },
  survey: { label: "Customer studies", token: "--g-survey", shape: "round-pentagon" },
  price: { label: "Price list", token: "--g-price", shape: "round-tag" },
  spec: { label: "Technical data", token: "--g-spec", shape: "barrel" },
  product: { label: "Series & variants", token: "--g-product", shape: "round-rectangle" },
  market: { label: "Markets", token: "--g-market", shape: "hexagon" },
  sales: { label: "Sales volumes", token: "--g-sales", shape: "round-hexagon" },
  model_output: { label: "Model outputs", token: "--g-model", shape: "diamond" },
  caveat: { label: "Caveats", token: "--g-caveat", shape: "triangle" },
};
// Rings from the centre outwards: the idea, its features, recommendations, then the evidence behind them.
const RING: Record<string, number> = {
  Idea: 10, Feature: 9, Recommendation: 8, VerdictCell: 7, Series: 7, Market: 7, Domain: 6, FitmentSummary: 6,
  SurveyScore: 5, SalesVolume: 5, SurveyAttribute: 5, Reason: 5, ModelArtifact: 4, EBMTerm: 4, OptionItem: 3, TechSpec: 3,
  Comment: 2, Caveat: 1,
};
const SCHEMA_RING: Record<string, number> = { Feature: 10 };

function cssVar(name: string) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || "#8e8e8e";
}
const short = (s: string, n = 30) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

export default function EvidenceGraph({
  evaluation,
  focus,
  onFocus,
}: {
  evaluation: AgentEvaluation;
  focus: string | null;
  onFocus: (id: string | null) => void;
}) {
  const [mode, setMode] = useState<"evaluation" | "schema">("evaluation");
  const { data: schema } = useApi<GraphSchema>(mode === "schema" ? "/api/graph/schema" : null);
  const box = useRef<HTMLDivElement>(null);
  const cy = useRef<Core | null>(null);
  const [selected, setSelected] = useState<string | null>(null);

  const elements = useMemo<ElementDefinition[]>(() => {
    if (mode === "schema") {
      if (!schema) return [];
      const maxLog = Math.log10(Math.max(...schema.node_types.map((t) => t.count)));
      const nodes = schema.node_types.map((t) => ({
        data: {
          id: t.type, label: `${t.type}\n${fmtInt(t.count)}`, group: t.group, ring: SCHEMA_RING[t.type] ?? 1,
          color: cssVar(GROUPS[t.group]?.token ?? "--g-spec"), shape: GROUPS[t.group]?.shape ?? "ellipse",
          size: 26 + 34 * (Math.log10(t.count + 1) / maxLog), cited: false,
        },
      }));
      const types = new Set(schema.node_types.map((t) => t.type));
      const edges = schema.edge_types
        .filter((e) => types.has(e.source) && types.has(e.target))
        .map((e, i) => ({ data: { id: `s${i}`, source: e.source, target: e.target, rel: `${e.rel} · ${fmtInt(e.count)}` } }));
      return [...nodes, ...edges];
    }
    const g = evaluation.graph;
    return [
      ...g.nodes.map((n) => {
        const grp = n.type === "Recommendation" ? "model_output" : n.group;
        return {
          data: {
            id: n.id, label: short(n.type === "Comment" ? n.id.replace("comment:", "") : n.label), group: grp, type: n.type,
            ring: RING[n.type] ?? 1, color: cssVar(GROUPS[grp]?.token ?? "--g-spec"),
            shape: n.type === "Recommendation" ? "round-diamond" : GROUPS[grp]?.shape ?? "ellipse",
            size: n.type === "Idea" ? 46 : n.chosen ? 38 : n.type === "Recommendation" ? 28 : 20, cited: n.cited,
          },
        };
      }),
      ...g.edges.map((e) => ({ data: { id: e.id, source: e.source, target: e.target, rel: e.rel } })),
    ];
  }, [mode, schema, evaluation]);

  useEffect(() => {
    if (!box.current || !elements.length) return;
    const font = getComputedStyle(document.body).fontFamily;
    const instance = cytoscape({
      container: box.current,
      elements,
      wheelSensitivity: 0.2,
      minZoom: 0.2,
      maxZoom: 3,
      style: [
        {
          selector: "node",
          style: {
            "background-color": "data(color)", shape: "data(shape)" as never, width: "data(size)", height: "data(size)",
            label: "data(label)", "font-family": font, "font-size": mode === "schema" ? 11 : 9, color: "#262626",
            "text-valign": "bottom", "text-margin-y": 4, "text-wrap": "wrap", "text-max-width": "120px",
            "border-width": 0, "overlay-opacity": 0,
          },
        },
        { selector: "node[?cited]", style: { "border-width": 3, "border-color": "#1c69d4" } },
        { selector: "node:selected", style: { "border-width": 4, "border-color": "#262626" } },
        {
          selector: "edge",
          style: {
            width: 1, "line-color": "#cccccc", "target-arrow-color": "#cccccc", "target-arrow-shape": "triangle", "arrow-scale": 0.6,
            "curve-style": "bezier", ...(mode === "schema"
              ? { label: "data(rel)", "font-size": 8, color: "#666666", "text-rotation": "autorotate", "font-family": font,
                  "text-background-color": "#ffffff", "text-background-opacity": 1, "text-background-padding": "2px" }
              : {}),
          },
        },
        {
          selector: "edge.hl",
          style: {
            "line-color": "#1c69d4", "target-arrow-color": "#1c69d4", width: 2, label: "data(rel)", "font-size": 8, color: "#1c69d4",
            "font-family": font, "text-rotation": "autorotate", "text-background-color": "#ffffff", "text-background-opacity": 1,
            "text-background-padding": "2px",
          },
        },
        { selector: ".faded", style: { opacity: 0.18 } },
      ],
      layout: {
        name: "concentric",
        concentric: (n: cytoscape.NodeSingular) => n.data("ring"),
        levelWidth: () => 1,
        minNodeSpacing: mode === "schema" ? 40 : 14,
        animate: false,
      } as cytoscape.LayoutOptions,
    });
    const highlight = (id: string | null) => {
      instance.elements().removeClass("faded hl");
      if (!id) return;
      const node = instance.getElementById(id);
      if (!node.length) return;
      const hood = node.closedNeighborhood();
      instance.elements().not(hood).addClass("faded");
      node.connectedEdges().addClass("hl");
      instance.nodes().unselect();
      node.select();
    };
    instance.on("tap", "node", (e) => {
      const id = e.target.id() as string;
      highlight(id);
      setSelected(id);
      if (mode === "evaluation") onFocus(id);
    });
    instance.on("tap", (e) => {
      if (e.target === instance) {
        highlight(null);
        setSelected(null);
      }
    });
    cy.current = instance;
    return () => {
      instance.destroy();
      cy.current = null;
    };
  }, [elements, mode, onFocus]);

  // Focus requested from outside (a citation's "Show in knowledge graph")
  useEffect(() => {
    if (!focus || mode !== "evaluation" || !cy.current) return;
    const node = cy.current.getElementById(focus);
    setSelected(focus);
    if (node.length) {
      cy.current.elements().removeClass("faded hl");
      cy.current.elements().not(node.closedNeighborhood()).addClass("faded");
      node.connectedEdges().addClass("hl");
      cy.current.nodes().unselect();
      node.select();
      cy.current.animate({ center: { eles: node }, zoom: 1.4 }, { duration: 300 });
    }
  }, [focus, mode, elements]);

  const present = mode === "schema"
    ? new Set(schema?.node_types.map((t) => t.group))
    : new Set(evaluation.graph.nodes.map((n) => (n.type === "Recommendation" ? "model_output" : n.group)));
  const inGraph = selected && !selected.startsWith("rec:") && !selected.startsWith("idea:") && mode === "evaluation";

  return (
    <div className="graph">
      <div className="graph__bar">
        <div className="tabs graph__tabs" role="tablist" aria-label="Graph view">
          <button className="tab" role="tab" aria-selected={mode === "evaluation"} onClick={() => setMode("evaluation")}>
            This evaluation ({evaluation.graph.nodes.length} nodes)
          </button>
          <button className="tab" role="tab" aria-selected={mode === "schema"} onClick={() => setMode("schema")}>
            How all the data connects{schema ? ` (${fmtInt(schema.n_nodes)} nodes)` : ""}
          </button>
        </div>
        <ul className="legend" aria-label="Legend">
          {Object.entries(GROUPS)
            .filter(([k]) => present.has(k))
            .map(([k, g]) => (
              <li key={k}>
                <span className="legend__swatch" style={{ background: `var(${g.token})` }} aria-hidden />
                {g.label}
              </li>
            ))}
          {mode === "evaluation" && (
            <li>
              <span className="legend__swatch legend__swatch--cited" aria-hidden />
              Cited by a fact
            </li>
          )}
        </ul>
      </div>
      <div className="graph__body">
        <div className="graph__canvas" ref={box} role="img" aria-label={mode === "schema" ? "Schema of the knowledge graph" : "Knowledge-graph neighbourhood of this evaluation"} />
        <aside className="graph__inspector" aria-live="polite">
          {mode === "schema" ? (
            <SchemaInfo schema={schema} selected={selected} />
          ) : inGraph ? (
            <NodeInspector nodeId={selected!} onSelect={(id) => onFocus(id)} />
          ) : selected ? (
            <VirtualInfo id={selected} evaluation={evaluation} />
          ) : (
            <p className="small muted">
              Select a node to see its source (table, PDF page or model file), its attributes and how it connects. Blue rings mark
              nodes that a fact in the brief cites.
            </p>
          )}
        </aside>
      </div>
    </div>
  );
}

function SchemaInfo({ schema, selected }: { schema: GraphSchema | null; selected: string | null }) {
  if (!schema) return <p className="small muted">Loading the schema…</p>;
  if (!selected)
    return (
      <div className="stack">
        <p className="eyebrow">Knowledge graph</p>
        <p className="small">
          {fmtInt(schema.n_nodes)} nodes and {fmtInt(schema.n_edges)} edges built from the processed tables and the model outputs.
          Select a type to see its relations.
        </p>
        <p className="caption">
          {schema.checks.filter((c) => c.ok).length} of {schema.checks.length} integrity checks against the source tables passed
          (built {schema.built_at}).
        </p>
      </div>
    );
  const t = schema.node_types.find((x) => x.type === selected);
  const rels = schema.edge_types.filter((e) => e.source === selected || e.target === selected);
  return (
    <div className="stack">
      <p className="eyebrow">{t?.group}</p>
      <h3 className="inspector__title">{selected}</h3>
      <p className="small">{fmtInt(t?.count ?? 0)} nodes</p>
      <ul className="rels">
        {rels.map((e, i) => (
          <li key={i} className="small">
            {e.source} <strong>{e.rel}</strong> {e.target} <span className="caption">{fmtInt(e.count)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

function VirtualInfo({ id, evaluation }: { id: string; evaluation: AgentEvaluation }) {
  if (id.startsWith("idea:"))
    return (
      <div className="stack">
        <p className="eyebrow">Idea (this request)</p>
        <h3 className="inspector__title">{evaluation.spec.idea}</h3>
        <p className="small">
          Matched to {evaluation.spec.features.map((f) => f.feature).join(", ") || "no feature in the data"}.
        </p>
      </div>
    );
  const facts = evaluation.facts.filter((f) => f.source.node_id === id);
  const [feature, series, market] = id.slice(4).split("|");
  return (
    <div className="stack">
      <p className="eyebrow">Recommendation (decision engine)</p>
      <h3 className="inspector__title">
        {feature}: {series} {market}
      </h3>
      <ul className="bullets small">
        {facts.map((f) => (
          <li key={f.id}>{f.statement}</li>
        ))}
      </ul>
      <p className="caption">Computed by DecisionEngine.evaluate from the verdict cell, survey score and sales volume it connects to.</p>
    </div>
  );
}

import { fmtNum, useApi } from "../api";
import type { NodeView } from "../types";
import { ErrorState } from "./marks";

const HIDE = new Set(["shape"]);

/** One knowledge-graph node: provenance first, then attributes, then its relations. */
export default function NodeInspector({ nodeId, onSelect }: { nodeId: string; onSelect: (id: string) => void }) {
  const { data, error, loading } = useApi<NodeView>(`/api/graph/node/${encodeURIComponent(nodeId)}`);
  if (error) return <ErrorState message={error} />;
  if (loading || !data) return <p className="small muted">Loading {nodeId}…</p>;
  const attrs = Object.entries(data.attributes).filter(([k, v]) => v !== null && v !== "" && !HIDE.has(k) && k !== "text");
  const text = typeof data.attributes.text === "string" ? (data.attributes.text as string) : null;
  const shape = Array.isArray(data.attributes.shape) ? (data.attributes.shape as { bin: string; score: number }[]) : null;
  return (
    <div className="stack inspector">
      <p className="eyebrow">{data.type}</p>
      <h3 className="inspector__title">{data.label}</h3>
      <dl className="kv">
        <dt>Source</dt>
        <dd>
          {data.prov.kind}: {data.prov.ref}
        </dd>
        {data.prov.key && (
          <>
            <dt>Key</dt>
            <dd>{data.prov.key}</dd>
          </>
        )}
        {data.prov.page && (
          <>
            <dt>Page</dt>
            <dd>{data.prov.page}</dd>
          </>
        )}
      </dl>
      {text && <blockquote className="quote">“{text}”</blockquote>}
      {attrs.length > 0 && (
        <dl className="kv">
          {attrs.slice(0, 18).map(([k, v]) => (
            <Attr key={k} k={k} v={v} />
          ))}
        </dl>
      )}
      {shape && (
        <table className="table">
          <thead>
            <tr>
              <th>Value</th>
              <th className="r">Log-odds</th>
            </tr>
          </thead>
          <tbody>
            {shape.slice(0, 12).map((s) => (
              <tr key={s.bin}>
                <td>{s.bin}</td>
                <td className="r num">{s.score > 0 ? "+" : ""}{fmtNum(s.score)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <div className="stack">
        {data.neighbours.map((g) => (
          <div key={`${g.direction}-${g.rel}`}>
            <p className="caption">
              {g.direction === "out" ? "→" : "←"} {g.rel} · {g.total}
            </p>
            <div className="chips">
              {g.items.slice(0, 6).map((n) => (
                <button key={n.id} className="chip chip--small" onClick={() => onSelect(n.id)} title={n.id}>
                  {n.label.length > 34 ? `${n.label.slice(0, 33)}…` : n.label}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function Attr({ k, v }: { k: string; v: unknown }) {
  const shown =
    typeof v === "number" ? (Number.isInteger(v) ? v.toLocaleString("en-GB") : fmtNum(v, Math.abs(v) < 1 ? 3 : 2))
      : typeof v === "boolean" ? (v ? "yes" : "no")
      : Array.isArray(v) ? v.slice(0, 6).join(", ") + (v.length > 6 ? ` (+${v.length - 6})` : "")
      : String(v);
  return (
    <>
      <dt>{k.replace(/_/g, " ")}</dt>
      <dd className="num">{shown.length > 160 ? `${shown.slice(0, 159)}…` : shown}</dd>
    </>
  );
}

