// UI walk-through of the local app: hero -> interpret -> review -> evaluate -> sections; screenshots + console errors.
const { chromium } = require('playwright');
const OUT = process.argv[2];
const BASE = process.argv[3] || 'http://127.0.0.1:8011';
const IDEA = process.argv[4] || 'Make seat massage standard on the 5 Series in Europe';
const W = Number(process.argv[5] || 1440);

(async () => {
  const b = await chromium.launch({ headless: true });
  const page = await b.newPage({ viewport: { width: W, height: 900 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(String(e)));
  await page.goto(BASE, { waitUntil: 'networkidle' });
  await page.screenshot({ path: `${OUT}/ui_${W}_1_hero.png` });
  const font = await page.evaluate(() => document.fonts.check('300 16px "BMW Type Next Web"'));
  await page.fill('#idea', IDEA);
  await page.click('.stage__cta');
  await page.waitForSelector('#review', { timeout: 20000 });
  await page.waitForTimeout(600);
  await page.locator('#review').screenshot({ path: `${OUT}/ui_${W}_2_review.png` });
  await page.click('#review .btn');
  await page.waitForSelector('#overview', { timeout: 20000 });
  await page.waitForTimeout(1500);
  for (const id of ['overview', 'explanation', 'markets', 'equipment', 'graph', 'verification', 'decision']) {
    await page.evaluate((i) => document.getElementById(i).scrollIntoView(), id);
    await page.waitForTimeout(id === 'graph' ? 2500 : 500);
